{
    "properties": {
        "credentials": {
            "description": "Credentials to authenticate with Minio server",
            "properties": {
                "access-key": {
                    "default": "minio",
                    "description": "Access Key",
                    "type": "string"
                },
                "secret-key": {
                    "default": "minio123",
                    "description": "Secret Key",
                    "type": "string"
                }
            },
            "required": [
                "access-key",
                "secret-key"
            ],
            "type": "object"
        },
        "networking": {
            "description": "Networking properties for Minio on DC/OS",
            "properties": {
                "port": {
                    "default": 9000,
                    "description": "Port on which Minio service is available",
                    "type": "number"
                },
                "public-access": {
                    "default": true,
                    "description": "Enables public access to Minio server if true",
                    "type": "boolean"
                }
            },
            "required": [
                "port"
            ],
            "type": "object"
        },
        "resource": {
            "description": "Resource properties for Minio on DC/OS",
            "properties": {
                "cpus": {
                    "default": 1,
                    "description": "CPU shares to allocate to service instance",
                    "minimum": 0.5,
                    "type": "number"
                },
                "mem": {
                    "default": 1024,
                    "description": "Memory to allocate to service instance",
                    "minimum": 1024,
                    "type": "number"
                }
            },
            "required": [
                "cpus",
                "mem"
            ],
            "type": "object"
        },
        "service": {
            "description": "Service properties for Minio on DC/OS",
            "properties": {
                "name": {
                    "default": "minio",
                    "description": "Name of this service instance",
                    "type": "string"
                }
            },
            "required": [
                "name"
            ],
            "type": "object"
        },
        "storage": {
            "description": "Storage properties for Minio on DC/OS",
            "properties": {
                "volume-size": {
                    "default": 1024,
                    "description": "Size of volume in MiB",
                    "type": "number"
                }
            },
            "required": [
                "volume-size"
            ],
            "type": "object"
        }
    }
}

