            "description": "Name of the endpoint",
            "examples": [
                "bar"
            ],
            "type": "string"
        },
        "endpointType": {
            "description": "Endpoint protocol type, either http or tchannel",
            "enum": [
                "http",
                "tchannel"
            ],
            "examples": [
                "http"
            ],
            "type": "string"
        },
