                "github.com/uber/zanzibar/examples/example-gateway/endpoints/contacts"
            ],
            "type": "string"
        },
        "workflowType": {
            "description": "Workflow type, either httpClient, tchannelClient or custom",
            "enum": [
                "custom",
                "httpClient",
                "tchannelClient"
            ],
            "examples": [
                "custom"
            ],
            "type": "string"
        }
